R=list(range(12)); T=lambda x:(x+1)%12; I=lambda x:(-x)%12; A=lambda x:(x+6)%12; rho=lambda x:(11-x)%12
F={'T':T,'I':I,'A':A,'rho':rho}; perms={k:tuple(f(i) for i in R) for k,f in F.items()}
compose=lambda p,q:tuple(p[q[i]] for i in R)
idp=tuple(R)
G={idp}; pending=[idp]
while pending:
 x=pending.pop()
 for y in perms.values():
  for z in [compose(x,y),compose(y,x)]:
   if z not in G:G.add(z);pending.append(z)
# algebra: all dihedral D12 (24)? T and I yes.
assert len(G)==24
center=lambda p:all(compose(p,q)==compose(q,p) for q in G)
Z=[p for p in G if center(p)]
orbits=[]; unseen=set(R)
while unseen:
 x=min(unseen); orb=sorted({p[x] for p in G});orbits.append(orb);unseen-=set(orb)
stabilizers={str(x):sum(p[x]==x for p in G) for x in R}
Aperm=perms['A']; assert center(Aperm)
# conjugacy classes
classes=[]; leftover=set(G)
while leftover:
 a=next(iter(leftover)); cls=set()
 for b in G:
  inv=next(p for p in G if compose(p,b)==idp)
  cls.add(compose(compose(b,a),inv))
 classes.append(cls); leftover-=cls
# Dn parity-preserving orientation map generated by T^2 and I has two 6 element orbits
H={idp}; todo=[idp]; gen=[compose(perms['T'],perms['T']),perms['I']]
while todo:
 x=todo.pop()
 for y in gen:
  z=compose(x,y)
  if z not in H:H.add(z);todo.append(z)
assert len(H)==12
# Novel within project: minimal generators and subgroup size conditional
assert all(compose(perms['rho'],perms['I'])[i]==(i-1)%12 for i in R)
# test entire generators, permutation preservation
checks=[]
def check(name,good,details=None):checks.append(dict(test=name,passed=bool(good),details=details))
for k,f in F.items():
 check('bijection_'+k,sorted(perms[k])==R)
 check('angular_transport_'+k,all(30*f(x)%360=={'T':lambda y:(y+30)%360,'I':lambda y:-y%360,'A':lambda y:(y+180)%360,'rho':lambda y:(330-y)%360}[k](30*x) for x in R))
for k in ['I','A','rho']:check('involution_'+k,all(F[k](F[k](x))==x for x in R))
for k in R:check('offset_'+str(k),len({(x+k)%12 for x in R})==12)
for k in R:check('element_modality_crt_'+str(k),sum(x%4==k%4 and x%3==k%3 for x in R)==1)
check('dihedral_size_24',len(G)==24)
check('center_size_2',len(Z)==2)
check('single_transitive_orbit',orbits==[R])
check('point_stabilizer_order_2',set(stabilizers.values())=={2})
check('conjugacy_classes_9',len(classes)==9) # D12 even has n/2+3 =9
check('parity_subgroup_size_12',len(H)==12)
check('RAP_rho_Tinv_I',all(rho(x)==(I(x)-1)%12 for x in R))
check('negative_A0_not5',A(0)!=5)
check('negative_rho0_not0',rho(0)!=0)
check('negative_quotient_not6',len({min(k,12-k) for k in R})!=6)
check('negative_empty_intersection',not (set() & set(R)))
assert all(q['passed'] for q in checks)
