(O/'OPERATOR_ALGEBRA.md').write_text(f'''# Computed finite algebra\n\n- `T(x)=x+1`; `I(x)=-x`, `A(x)=x+6`, `rho(x)=11-x` modulo 12.\n- Generated permutation group: **{len(G)} elements**, dihedral `D_12` (order 24, symmetries of twelve-gon).\n- `A=T^6`, `rho=T^{{-1}} I`; generators `T,I` suffice; no extra dimension from four names.\n- Center has **{len(Z)} elements**, identity and antipodal `A`.\n- Conjugacy classes: **{len(classes)}**.\n- Orbit on vertices: {orbits}. Stabilizer size at each vertex: 2.\n- Parity-preserving subgroup `<T²,I>` has order **{len(H)}**, with even/odd orbits.\n- Full angular transport `h(x)=30x mod 360` passes 4×12 exhaustive commuting checks.\n- `rho` is a legitimate derived dihedral action, **not claimed verbatim in the course**.\n''')
# Image angular profile, independent disjoint radial bands; use radial shift prediction of orientation gradient field
imgpath=P/'Emergent Artifact .jpeg'; im=cv2.imread(str(imgpath),0);assert im is not None
height,width=im.shape
# fixed near-visible center; explicit no objective center verification
cx,cy=460,455
# 12-sector feature energy per radial band. Bilinear sample, angles 12*30 from -pi to pi; sectors sampled 25 angles each.
gray=im.astype(np.float32)/255
sobx=cv2.Sobel(gray,cv2.CV_32F,1,0);soby=cv2.Sobel(gray,cv2.CV_32F,0,1)
energy=np.hypot(sobx,soby)
angles=np.arange(360,dtype=np.float32)*np.pi/180
features=[]
for r0,r1 in [(24,44),(44,64),(64,84),(84,104),(104,124),(124,144)]:
 vals=[]
 for rad in np.linspace(r0,r1,22):
  xi=(cx+rad*np.cos(angles)).astype(np.float32);yi=(cy-rad*np.sin(angles)).astype(np.float32)
  pix=cv2.remap(energy,xi.reshape(1,-1),yi.reshape(1,-1),cv2.INTER_LINEAR)[0]
  vals.append(pix)
 mean=np.mean(vals,axis=0)
 sectors=np.asarray([float(np.mean(mean[30*j:30*(j+1)])) for j in range(12)])
 features.append(sectors)
features=np.asarray(features)
# A prospective translation of sector patterns between radial scales using first two radii training, and last four held-out. This is an engineered test, not sourced law.
train=features[:2];test=features[2:]
# choose offset maximizing corr between first two band vectors, hold on other four adjacent pair comparisons
cc=lambda a,b:float(np.corrcoef(a,b)[0,1]) if np.std(a)>1e-12 and np.std(b)>1e-12 else 0
scores=[cc(train[0],np.roll(train[1],shift)) for shift in range(12)]
shift=max(range(12),key=lambda k:scores[k]);train_score=scores[shift]
held=[cc(test[j],np.roll(test[j+1],shift)) for j in range(3)]
held_competing=[float(np.mean([cc(test[j],np.roll(test[j+1],k)) for j in range(3)])) for k in range(12)]
rank=sorted(held_competing,reverse=True).index(float(np.mean(held)))+1
# correction for 12 possible cyclic shifts using empirical exact null over all 12 shifts
p_exact=sum(x>=np.mean(held)-1e-12 for x in held_competing)/12
image_report={'image':str(imgpath),'sha256':hashlib.sha256(imgpath.read_bytes()).hexdigest(),'size':[width,height],'center':[cx,cy],'center_status':'visual candidate, not mathematically optimized','feature':'mean Sobel magnitude in twelve 30-degree sectors, six radial annuli','radii':[[24,44],[44,64],[64,84],[84,104],[104,124],[124,144]],'train_selected_shift':shift,'train_correlation':train_score,'heldout_correlations':held,'heldout_mean':float(np.mean(held)),'all_twelve_shift_control_means':held_competing,'heldout_rank':rank,'exact_shift_null_p':p_exact,'source_to_image_semantic_operator_verified':False,'limitation':'Annular cross-scale angular shifts were not specified by Tobey as an image operator; test assesses engineered local recurrence, not direct physical spacetime mapping.'}
